def add_light_roles(apps, schema_editor):
    """Organizations created before light users existed get the default
    light roles too. Permission labels are filled in properly by the
    post-migrate sync (organizations.catalog.sync_permissions)."""
    Company = apps.get_model('accounts', 'Company')
    Role = apps.get_model('organizations', 'Role')
    Permission = apps.get_model('organizations', 'Permission')
    for company in Company.objects.filter(memberships__isnull=False).distinct():
        for key, (name, description, codes) in LIGHT_ROLES.items():
            role, created = Role.objects.get_or_create(
                company=company, key=key,
                defaults={'name': name, 'description': description, 'is_system': True, 'user_type': 'light'},
            )
            if created:
                role.permissions.set([
                    Permission.objects.get_or_create(code=code, defaults={'label': code, 'module': ''})[0] for code in codes
                ])


